target.css:
:root {
  --ink: #273b35;
  --paper: #fffdf7;
  --accent: #e7b45f;
}

* {
  box-sizing: border-box;
}

.pickup-token {
  width: 430px;
  padding: 16px;
  background: var(--paper);
  color: var(--ink);
  border: 2px solid var(--ink);
  border-radius: 14px 4px 14px 4px;
}

.token-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.eyebrow {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.stamp {
  padding: 4px 8px;
  background: var(--accent);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.pickup-token h1 {
  margin: 14px 0 4px;
  font-size: 22px;
  line-height: 1.1;
}

.note {
  margin: 0;
  font-size: 14px;
  line-height: 1.4;
}
